    key=('res_depth',rule,ep,'equalLN' if a['n_ln']==b['n_ln'] else 'moreLN' if a['n_ln']>b['n_ln'] else 'lessLN')
    stats[key].append((a['mean']<b['mean'],a['mean']/b['mean'],sid))
   if a['depth']==2 and not a['residual'] and a['activation'] in ['silu','gelu'] and a['layer_norm'][-1] and b['residual'] and b['depth']<=3 and b['activation'] in ['relu','leaky_relu'] and b['layer_norm'][-1]:
